import { prisma } from "@/lib/prisma";
import { requireVendor } from "@/lib/rbac";
import { VerificationForm } from "./VerificationForm";
export default async function VendorVerificationPage() { const user = await requireVendor(); const vendor = await prisma.vendor.findUnique({ where: { userId: user.id }, include: { verifications: { orderBy: { createdAt: "desc" } } } }); return <section className="space-y-6"><div><h1 className="text-2xl font-black">Verification status</h1><p className="mt-1 text-sm text-gray-500">Track your shop verification documents and review outcome.</p></div><div className="rounded-2xl border bg-white p-6 dark:bg-gray-900"><p className="text-sm">Current status: <strong>{vendor?.status || "PENDING"}</strong></p><div className="mt-5 space-y-3">{vendor?.verifications.map((item) => <div key={item.id} className="rounded-xl border p-4 text-sm"><strong>{item.documentType}</strong><span className="ml-2 text-gray-500">{item.status}</span>{item.adminNotes && <p className="mt-2 text-gray-500">{item.adminNotes}</p>}</div>)}</div><VerificationForm /></div></section>; }
